DigitalValueSimplified.Process_Desc:=	DigitalValue.EXT_General.Process_Desc;
DigitalValueSimplified.Process_TAG:=		DigitalValue.EXT_General.Process_TAG;

CASE Cfg_StateNumber OF 
	
	0://State 1 (Module fault)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_1.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_1.Sts_Desc;
	
	1://State 2 (Value stuck)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_2.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_2.Sts_Desc;
	
	2://State 3 (Unstable value)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_3.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_3.Sts_Desc;
	
	3://State 4 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_4.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_4.Sts_Desc;
	
	4://State 5 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_5.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_5.Sts_Desc;
	
	5://State 6 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_6.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_6.Sts_Desc;
	
	6://State 7 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_7.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_7.Sts_Desc;
	
	7://State 8 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_8.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_8.Sts_Desc;
	
	8://State 9 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_9.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_9.Sts_Desc;
	
	9://State 10 (Custom)
	DigitalValueSimplified.Process_State_Value:=DigitalValue.EXT_Engineering.StateCfg_10.Sts_State;
	DigitalValueSimplified.Process_State_Desc:=DigitalValue.EXT_Engineering.StateCfg_10.Sts_Desc;
	
END_CASE;
